package com.ml.tblandroidtxt;import org.json.JSONArray;import org.json.JSONObject;
/** One checkpointable FINAL_QA scene, used only after independent evidence was closed. */
public final class EditorialL3SceneContract {
 public static String schema(){return "{\"sceneId\":\"string\",\"rawStart\":\"anchor\",\"rawEnd\":\"anchor\",\"output\":\"complete final scene\",\"outputComplete\":true,\"changeSet\":[{\"id\":\"string\",\"position\":\"string\",\"before\":\"string\",\"after\":\"string\",\"reason\":\"string\",\"scope\":\"string\",\"status\":\"CLOSED\"}],\"finalReadThrough\":\"CLOSED\",\"gates\":{\"coverage\":\"CLOSED\",\"fidelity\":\"CLOSED\",\"referenceVoice\":\"CLOSED\",\"continuityStructure\":\"CLOSED\",\"change\":\"CLOSED\"}}";}
 public static String validate(String text){try{JSONObject r=new JSONObject(text);if(blank(r.optString("sceneId"))||blank(r.optString("rawStart"))||blank(r.optString("rawEnd"))||blank(r.optString("output"))||!r.optBoolean("outputComplete",false)||!"CLOSED".equals(r.optString("finalReadThrough")))return "L3 scene output is incomplete";JSONArray c=r.optJSONArray("changeSet");if(c==null)return "Missing L3 scene Change Set";for(int i=0;i<c.length();i++){JSONObject x=c.optJSONObject(i);if(x==null||blank(x.optString("id"))||blank(x.optString("position"))||blank(x.optString("before"))||blank(x.optString("after"))||blank(x.optString("reason"))||blank(x.optString("scope"))||!"CLOSED".equals(x.optString("status")))return "Incomplete L3 scene change";}JSONObject g=r.optJSONObject("gates");if(g==null)return "Missing L3 scene gates";for(String k:new String[]{"coverage","fidelity","referenceVoice","continuityStructure","change"})if(!"CLOSED".equals(g.optString(k)))return "L3 scene gate is open: "+k;return null;}catch(Exception e){return "Invalid L3 scene JSON";}}
 private static boolean blank(String x){return x==null||x.trim().isEmpty();}private EditorialL3SceneContract(){}
}
